func:
// Returns the stored record, or null when this actor has never received one
// -- no write either way. Mirrors demo_actor.py's GetMyData; v1 of this
// package has no delete, so there is no equivalent of the sample's
// clear_my_data.
msg.payload = msg.dapr.actor.stateExists ? msg.dapr.actor.state : null;
return [msg, null];

// Stores msg.payload with a server-set timestamp -- mirrors dapr/python-sdk's
// demo_actor.py SetMyData (see this tab's Comment for the source link). The
// request handler commits msg.dapr.actor.nextState only after the reply node
// accepts this proposal; this function never touches storage itself.
function fail(code, message) {
    msg.dapr.actor.error = { code, message };
    return [null, msg];
}

const data = msg.payload;
if (!data || typeof data !== 'object' || Array.isArray(data)) {
    return fail('INVALID_ARGUMENT', 'SetMyData requires a plain JSON object argument');
}

msg.dapr.actor.nextState = { ...data, ts: new Date().toISOString() };
msg.payload = null;
return [msg, null];

// Increments the persisted counter by 1. dapr/js-sdk's DemoActorCounterImpl
// keeps the counter in memory; this example persists { counter } in the
// actor's own record so it survives a restart.
const current = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
const counter = current + 1;
msg.payload = counter;
msg.dapr.actor.nextState = { counter };
return [msg, null];

// Increments by amount * multiplier (multiplier defaults to 1), mirroring
// DemoActorCounterImpl's countBy. Rejects a non-finite amount or multiplier
// rather than storing NaN/Infinity.
function fail(code, message) {
    msg.dapr.actor.error = { code, message };
    return [null, msg];
}

const arg = msg.payload || {};
const amount = arg.amount;
const multiplier = arg.multiplier === undefined ? 1 : arg.multiplier;
if (typeof amount !== 'number' || !Number.isFinite(amount)) {
    return fail('INVALID_ARGUMENT', 'countBy requires a finite numeric amount');
}
if (typeof multiplier !== 'number' || !Number.isFinite(multiplier)) {
    return fail('INVALID_ARGUMENT', 'countBy requires a finite numeric multiplier');
}

const current = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
const counter = current + amount * multiplier;
msg.payload = counter;
msg.dapr.actor.nextState = { counter };
return [msg, null];

// Returns the persisted counter, 0 when this actor has never been given one
// -- no write either way.
msg.payload = msg.dapr.actor.stateExists ? msg.dapr.actor.state.counter : 0;
return [msg, null];

delete msg.dapr.actor.nextState; // never propose a write from a failure path
msg.dapr.actor.error = { code: 'INTERNAL', message: 'unexpected error' };
return msg;
